import{a6 as r,aq as s,an as n,ay as t,cU as i,ax as d,aw as l,b_ as c,bJ as o}from"./index-dP4jQgVM.js";const h={},g={class:"lesson-page"},u={class:"shell"},v={class:"pager","aria-label":"Tutorialnavigation"};function m(b,e){const a=c("RouterLink");return o(),s("main",g,[n("div",u,[t(a,{to:"/medientechnik/figma",class:"back"},{default:i(()=>[...e[0]||(e[0]=[d("← Figma",-1)])]),_:1}),e[4]||(e[4]=l('<header data-v-446a1c46><p class="eyebrow" data-v-446a1c46>FIGMA FÜR ANFÄNGER · SCHRITT 2 VON 16</p><h1 data-v-446a1c46>Designdatei, Oberfläche und Navigation</h1><p class="goal" data-v-446a1c46>Du organisierst Dateien in einem Team, legst eine Designdatei an und bewegst dich sicher durch Figma.</p></header><p class="intro" data-v-446a1c46>Melde dich zunächst mit deiner <strong data-v-446a1c46>Schul-E-Mail-Adresse</strong> an. In diesem Schritt lernst du die Dateiübersicht und den Design-Editor kennen. Die Oberfläche und englische oder deutsche Bezeichnungen können je nach Konto und Version etwas anders aussehen.</p><section aria-labelledby="terms-title" data-v-446a1c46><h2 id="terms-title" data-v-446a1c46>Einfach erklärt</h2><dl data-v-446a1c46><div data-v-446a1c46><dt data-v-446a1c46>Team</dt><dd data-v-446a1c46>Ein gemeinsamer Bereich, in dem Mitglieder Dateien organisieren und zusammenarbeiten können.</dd></div><div data-v-446a1c46><dt data-v-446a1c46>Ordner / Projekt</dt><dd data-v-446a1c46>Ein Ordner bündelt zusammengehörige Dateien innerhalb eines Teams. Figma ersetzt die bisherige Bezeichnung „Projekt“ nach und nach durch „Ordner“ (Folder).</dd></div><div data-v-446a1c46><dt data-v-446a1c46>Drafts / Entwürfe</dt><dd data-v-446a1c46>Ein persönlicher Entwurfsbereich innerhalb eines Teams. Dateien können später in einen Teamordner verschoben werden.</dd></div><div data-v-446a1c46><dt data-v-446a1c46>Designdatei</dt><dd data-v-446a1c46>Dein Dokument für Bildschirmgestaltungen. Es enthält Seiten, Arbeitsflächen und die einzelnen Ebenen deiner Gestaltung.</dd></div></dl></section><section class="practice" aria-labelledby="browser-title" data-v-446a1c46><h2 id="browser-title" data-v-446a1c46>1. Die Dateiübersicht kennenlernen</h2><ol data-v-446a1c46><li data-v-446a1c46>Nach der Anmeldung siehst du die <strong data-v-446a1c46>Dateiübersicht</strong> (File browser). Bist du bereits in einer Datei, öffne das Figma-Menü und wähle <strong data-v-446a1c46>Back to files</strong>.</li><li data-v-446a1c46>Suche links den Namen des aktuellen Teams. Über das Menü neben dem Namen kannst du zwischen Teams wechseln, denen du angehörst.</li><li data-v-446a1c46>Öffne <strong data-v-446a1c46>Drafts</strong>, um deine Entwürfe des ausgewählten Teams zu sehen. Unter <strong data-v-446a1c46>Recents</strong> findest du zuletzt geöffnete Dateien; markierte Dateien erscheinen unter <strong data-v-446a1c46>Starred</strong>.</li><li data-v-446a1c46>Öffne die Ordnerübersicht des Teams, um gemeinsame Arbeiten zu finden. Je nach Plan und Berechtigung siehst du unterschiedliche Bereiche und Befehle.</li></ol></section><section class="practice" aria-labelledby="team-title" data-v-446a1c46><h2 id="team-title" data-v-446a1c46>2. Ein Team auswählen oder erstellen</h2><ol data-v-446a1c46><li data-v-446a1c46>Prüfe zuerst, ob deine Lehrkraft bereits ein Team für die Klasse eingerichtet oder dich eingeladen hat. Falls ja, wähle dieses Team über das Menü neben dem Teamnamen aus.</li><li data-v-446a1c46>Wenn du selbst ein Team erstellen sollst und dein Konto dies erlaubt, öffne das Menü neben dem Teamnamen und wähle <strong data-v-446a1c46>Create new</strong>. Je nach Schulkonto und Berechtigung kann der Weg über die Teamübersicht und <strong data-v-446a1c46>Team</strong> führen.</li><li data-v-446a1c46>Gib einen aussagekräftigen Teamnamen ein und folge den angezeigten Schritten. Personen kannst du gegebenenfalls über ihre Schul-E-Mail-Adresse einladen und ihre Berechtigung festlegen; die Einladung lässt sich auch später erledigen.</li><li data-v-446a1c46>Wähle den von der Schule vorgesehenen Zugang. Ein neu erstelltes Team kann einen eigenen Plan haben und gehört nicht automatisch zur bestehenden Schullizenz. Wenn Figma einen kostenpflichtigen Plan oder Zahlungsdaten verlangt, kläre das mit deiner Lehrkraft, bevor du fortfährst.</li></ol></section><section class="practice" aria-labelledby="folder-title" data-v-446a1c46><h2 id="folder-title" data-v-446a1c46>3. Ein Projekt als Ordner anlegen</h2><ol data-v-446a1c46><li data-v-446a1c46>Öffne das gewünschte Team und dort <strong data-v-446a1c46>All folders</strong> beziehungsweise die Ordnerübersicht. In älteren Ansichten kann stattdessen <strong data-v-446a1c46>Projects</strong> stehen.</li><li data-v-446a1c46>Wähle <strong data-v-446a1c46>+ Folder</strong>, gib zum Beispiel <strong data-v-446a1c46>Figma Übungen</strong> als Namen ein und lege fest, wer Zugriff haben soll. Bestätige die angezeigten Schritte und erstelle den Ordner.</li><li data-v-446a1c46>Öffne den Ordner. Hier kannst du zusammengehörige Dateien ablegen. Ob du Ordner erstellen und wer sie sehen oder bearbeiten darf, hängt von deinen Berechtigungen ab.</li></ol></section><section class="practice" aria-labelledby="file-title" data-v-446a1c46><h2 id="file-title" data-v-446a1c46>4. Eine Designdatei anlegen</h2><ol data-v-446a1c46><li data-v-446a1c46>Öffne deinen Übungsordner im Team oder für eine persönliche Übung den Bereich <strong data-v-446a1c46>Drafts</strong>.</li><li data-v-446a1c46>Wähle oben <strong data-v-446a1c46>+ Create → Design</strong>. Es öffnet sich eine neue Figma-Design-Datei. Eine Datei im Teamordner können berechtigte Teammitglieder finden; prüfe vor dem Teilen die Zugriffsrechte.</li><li data-v-446a1c46>Klicke auf den Dateinamen und benenne die Datei <strong data-v-446a1c46>Figma_Übung_Nachname</strong>. Ersetze „Nachname“ durch deinen eigenen Namen.</li><li data-v-446a1c46>Figma speichert Änderungen in der Datei automatisch. Kehre über <strong data-v-446a1c46>Figma-Menü → Back to files</strong> zur Dateiübersicht zurück und öffne deine Datei erneut.</li></ol></section><section aria-labelledby="interface-title" data-v-446a1c46><h2 id="interface-title" data-v-446a1c46>5. Die Arbeitsoberfläche verstehen</h2><dl data-v-446a1c46><div data-v-446a1c46><dt data-v-446a1c46>Canvas – Arbeitsfläche</dt><dd data-v-446a1c46>Die große Fläche in der Mitte. Hier platzierst du später Frames, Formen, Texte und Bilder. Du kannst dich auf ihr bewegen, ohne die Gestaltung selbst zu verschieben.</dd></div><div data-v-446a1c46><dt data-v-446a1c46>Werkzeugleiste</dt><dd data-v-446a1c46>Hier wählst du Werkzeuge zum Auswählen, Verschieben und Erstellen von Elementen. In der aktuellen Oberfläche befindet sie sich am unteren Rand; Position und Symbole können sich ändern.</dd></div><div data-v-446a1c46><dt data-v-446a1c46>Navigation und linke Seitenleiste</dt><dd data-v-446a1c46>Über die Navigation wechselst du zwischen Bereichen. In der Datei-Ansicht findest du links die Seiten und die Ebenen der aktuellen Seite. Dort lassen sich Elemente auswählen und ihre Reihenfolge erkennen.</dd></div><div data-v-446a1c46><dt data-v-446a1c46>Rechtes Eigenschaftenbedienfeld</dt><dd data-v-446a1c46>Wählst du ein Element aus, kannst du rechts seine Eigenschaften sehen und ändern, zum Beispiel Position, Größe und Farbe. Ohne Auswahl zeigt der Bereich andere Einstellungen.</dd></div><div data-v-446a1c46><dt data-v-446a1c46>Dateiname, Teilen und Zoom</dt><dd data-v-446a1c46>Über den Dateinamen erkennst und benennst du dein Dokument. Über die Freigabe steuerst du, wer Zugriff erhält. Die Zoomanzeige hilft dir, die Ansicht zu vergrößern oder zu verkleinern.</dd></div></dl></section><section class="practice" aria-labelledby="navigation-title" data-v-446a1c46><h2 id="navigation-title" data-v-446a1c46>6. Navigation ausprobieren</h2><ol data-v-446a1c46><li data-v-446a1c46><strong data-v-446a1c46>Arbeitsfläche verschieben:</strong> Halte die <strong data-v-446a1c46>Leertaste</strong> gedrückt und ziehe mit der Maus. Auf dem Trackpad kannst du mit zwei Fingern über die Fläche streichen. Das verschiebt nur deinen Blick auf die Arbeitsfläche.</li><li data-v-446a1c46><strong data-v-446a1c46>Zoomen:</strong> Ziehe auf dem Trackpad zwei Finger auseinander oder zusammen. Mit der Maus halte <strong data-v-446a1c46>⌘</strong> auf dem Mac beziehungsweise <strong data-v-446a1c46>Strg</strong> unter Windows gedrückt und bewege das Mausrad.</li><li data-v-446a1c46><strong data-v-446a1c46>Übersicht wiederfinden:</strong> Drücke <strong data-v-446a1c46>Umschalt + 1</strong>, um vorhandene Inhalte in die Ansicht einzupassen. Mit ausgewähltem Objekt zeigt <strong data-v-446a1c46>Umschalt + 2</strong> die Auswahl vergrößert.</li><li data-v-446a1c46><strong data-v-446a1c46>Element und Ebene suchen:</strong> Drücke <strong data-v-446a1c46>R</strong>, ziehe ein Rechteck auf und wähle es an. Suche die zugehörige Ebene links und die Eigenschaften rechts. Probiere anschließend das Auswahlwerkzeug mit <strong data-v-446a1c46>V</strong> aus.</li><li data-v-446a1c46><strong data-v-446a1c46>Zur Dateiübersicht zurückkehren:</strong> Nutze das Figma-Menü und <strong data-v-446a1c46>Back to files</strong>. Öffne die Datei erneut und kontrolliere, ob dein Rechteck noch vorhanden ist.</li></ol></section><section class="check" aria-labelledby="check-title" data-v-446a1c46><h2 id="check-title" data-v-446a1c46>Prüfe dein Ergebnis</h2><p data-v-446a1c46>Du findest dein Team und deinen Übungsordner, kannst deine benannte Designdatei erneut öffnen und Arbeitsfläche, Werkzeugleiste, Ebenenübersicht und Eigenschaftenbedienfeld zeigen. Du kannst die Ansicht verschieben und zoomen.</p></section><p data-v-446a1c46>Weiterführend: <a href="https://help.figma.com/hc/en-us/articles/14381406380183-Guide-to-the-file-browser" target="_blank" rel="noopener noreferrer" data-v-446a1c46>Figma: Dateiübersicht</a>, <a href="https://help.figma.com/hc/en-us/articles/360038006494-Create-and-manage-folders" target="_blank" rel="noopener noreferrer" data-v-446a1c46>Ordner erstellen</a>, <a href="https://help.figma.com/hc/en-us/articles/360039484194-Create-a-new-team" target="_blank" rel="noopener noreferrer" data-v-446a1c46>Team erstellen</a> und <a href="https://help.figma.com/hc/en-us/articles/15297425105303-Explore-design-files" target="_blank" rel="noopener noreferrer" data-v-446a1c46>Design-Editor kennenlernen</a> (englisch).</p>',11)),n("nav",v,[t(a,{to:"/medientechnik/figma/tutorial/1"},{default:i(()=>[...e[1]||(e[1]=[d("← Schritt 1",-1)])]),_:1}),e[3]||(e[3]=n("span",null,"2 / 16",-1)),t(a,{to:"/medientechnik/figma/lerninhalte"},{default:i(()=>[...e[2]||(e[2]=[d("Übersicht Lerninhalte →",-1)])]),_:1})])])])}const k=r(h,[["render",m],["__scopeId","data-v-446a1c46"]]);export{k as default};
